<script setup lang="ts">
import { computed } from "vue";
import { Head, Link } from "@inertiajs/vue3";
import { ArrowRight, BriefcaseBusiness, CheckCircle2, ClockAlert, Users } from "@lucide/vue";
import AppLayout from "@/Layouts/AppLayout.vue";
const props = defineProps<{ staff: any[]; periodLabel: string }>();
const totals = computed(() => ({ jobs: props.staff.reduce((n, s) => n + s.totalJobs, 0), completed: props.staff.reduce((n, s) => n + s.completed, 0), overdue: props.staff.reduce((n, s) => n + s.overdue, 0) }));
const rate = (s: any) => s.completed + s.processing ? Math.round(s.completed / (s.completed + s.processing) * 100) + "%" : "—";
</script>
<template>
    <Head title="Produktivitas Karyawan" /><AppLayout><main class="mx-auto max-w-7xl space-y-6 p-4">
        <header><p class="text-xs font-black uppercase tracking-[.18em] text-[var(--primary)]">Kinerja tim</p><h1 class="mt-1 text-2xl font-black sm:text-3xl">Produktivitas Karyawan</h1><p class="mt-1 text-sm text-slate-500">Ringkasan berkas sebagai PIC dan tugas sepanjang waktu · absensi {{ periodLabel }}.</p></header>
        <section class="grid grid-cols-2 gap-3 lg:grid-cols-4"><article v-for="item in [{label:'Pegawai',value:staff.length,icon:Users},{label:'Berkas PIC',value:totals.jobs,icon:BriefcaseBusiness},{label:'Berkas selesai',value:totals.completed,icon:CheckCircle2},{label:'Lewat deadline',value:totals.overdue,icon:ClockAlert}]" :key="item.label" class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="flex justify-between gap-2 text-slate-500"><span class="text-xs font-bold uppercase">{{ item.label }}</span><component :is="item.icon" class="h-5 w-5 text-[var(--primary)]" /></div><p class="mt-3 text-3xl font-black text-slate-900">{{ item.value }}</p></article></section>
        <div><h2 class="text-lg font-black">Statistik per pegawai</h2><p class="text-xs text-slate-500">Pilih pegawai untuk melihat rincian dan cara perhitungan.</p></div>
        <div v-if="staff.length" class="grid gap-4 md:grid-cols-2"><Link v-for="s in staff" :key="s.id" :href="`/dashboard/productivity/${encodeURIComponent(s.id)}`" class="group rounded-3xl border border-slate-200 bg-white p-5 shadow-sm transition hover:-translate-y-0.5 hover:border-[var(--primary)] hover:shadow-md"><div class="flex items-center justify-between gap-3"><div><h3 class="text-lg font-black text-slate-900">{{ s.fullName || s.username }}</h3><p class="text-xs font-bold text-slate-500">{{ s.role }}</p></div><ArrowRight class="h-5 w-5 text-[var(--primary)]" /></div><div class="mt-5 grid grid-cols-2 gap-2 sm:grid-cols-4"><div v-for="item in [{label:'Selesai',value:s.completed},{label:'Aktif',value:s.processing},{label:'Tugas',value:s.totalTasks},{label:'Penyelesaian',value:rate(s)}]" :key="item.label" class="rounded-xl bg-slate-50 p-3"><p class="text-[10px] font-bold uppercase text-slate-500">{{ item.label }}</p><p class="mt-1 text-xl font-black text-slate-900">{{ item.value }}</p></div></div><p class="mt-4 text-xs text-slate-500">{{ s.overdue }} lewat deadline · {{ s.workingDays === null ? '—' : s.presentDays }} hari hadir · {{ s.workingDays === null ? '—' : s.lateDays }} hari terlambat<span v-if="s.workingDays === null"> · profil absensi belum tersedia</span></p><p class="mt-3 text-right text-xs font-bold text-[var(--primary)]">Lihat detail KPI</p></Link></div><p v-else class="rounded-2xl bg-white p-6 text-sm text-slate-500">Belum ada data pegawai.</p>
    </main></AppLayout>
</template>
